import React, { Component } from "react";
import "./Signup.css";

export default class Signup extends Component {
    constructor(props) {
        super(props);
        this.state = {
            signupage: null,
        };
    }

    componentDidMount() {
        const pageName = "SignUp";
        fetch(`http://localhost:3001/${pageName}`) 
            .then(response => response.json())
            .then(page => {
                this.setState({ signupage: page });
            })
            .catch(error => console.error('Error fetching data:', error));
    }

    render() {
        const { signupage } = this.state;
        console.log(signupage);
        if (!signupage) return <div>PAGE NOT FOUND</div>;

        const textSignup = signupage.text;
        const leftsideContent = textSignup.leftside;
        const rightsideContent = textSignup.rightside;
        const buttonsdata = signupage.buttons;

        let leftContent = null;
        if (leftsideContent) {
            leftContent = leftsideContent.map((item, index) => (
                <input
                    key={index}
                    type={item.type}
                    className={item.className}
                    placeholder={item.placeholder}
                    required
                />
            ));
        }

        let rightContent = null;
        if (rightsideContent) {
            rightContent = rightsideContent.map((item, index) => (
                <input
                    key={index}
                    type={item.type}
                    className={item.className}
                    placeholder={item.placeholder}
                    required
                />
            ));
        }

        return (
            <div className="content-container">
                <div className="formbox">
                    <div className="button-box">
                        <div id="btn"></div>
                        {buttonsdata.map((value, index) => (
                            <button
                                key={index}
                                type={value.type}
                                className={value.className}
                            >
                                {value.text}
                            </button>
                        ))}
                    </div>

                    <div className="social-icons">
                        <img src={signupage.Img2} alt="fac" />
                        <img src={signupage.Img1} alt="fac" />
                    </div>

                    <form className="input-group">
                        <div className="input-left">
                            {leftContent}
                        </div>

                        <div className="input-right">
                            {rightContent}
                        </div>
                    </form>

                    <button type="submit" className="submit-btn">Sign up</button>

                </div>
            </div>
        );
    }
}
